import math
from functools import reduce

# Helper functions for GCD and LCM of a list of numbers
def gcd_list(numbers):
    if not numbers:
        return 0
    return reduce(math.gcd, numbers)

def lcm_list(numbers):
    if not numbers:
        return 1
    # LCM(a, b) = |a*b| / GCD(a, b)
    def lcm(a, b):
        return abs(a * b) // math.gcd(a, b)
    return reduce(lcm, numbers)

def calculate_N_n(n):
    good_partitions_count = 0
    # k runs from 1 to n-1
    for k in range(1, n):
        A_k = list(range(1, k + 1))
        B_k = list(range(k + 1, n + 1))

        lcm_A_k = lcm_list(A_k)
        gcd_B_k = gcd_list(B_k)

        if lcm_A_k == gcd_B_k:
            good_partitions_count += 1
            # print(f"n={n}, k={k}: A_k={A_k}, B_k={B_k}. LCM={lcm_A_k}, GCD={gcd_B_k}. GOOD.")

    return good_partitions_count

# Calculate N(3), N(4), N(5)
N3 = calculate_N_n(3)
N4 = calculate_N_n(4)
N5 = calculate_N_n(5)

print(f"N(3) = {N3}")
print(f"N(4) = {N4}")
print(f"N(5) = {N5}")

